fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

data class Pair100<A, B>(val first: A, val second: B)

fun combine100(left: Int, right: Int): Pair100<Int, Int> {
    return Pair100(left + 38, right + 18)
}
@JvmName("step101")
fun step101(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 45
}
sealed class Outcome102 {
    data class Success(val payload: String) : Outcome102()
    data object Failure : Outcome102()
}

fun describe102(outcome: Outcome102): String = when (outcome) {
    is Outcome102.Success -> outcome.payload
    Outcome102.Failure -> "failed"
}
